class pmi_ticket_collector:
    """
    | PMI Ticket collector class. It gives possibility to gather CPUE and CPRT PMI Records from gNB.
    | It reads gNB config from TestLine and creates necessary connections.
    | To use, you need to invoke :class:`prepare_pmi_tickets_config`, then :class:`start_collecting_pmi_tickets`.
    | At the end call :class:`stop_collecting_pmi_tickets`.
    | There are plenty of checkers and verifiers to ease the testing.
    """

    ROBOT_LIBRARY_SCOPE: str = "GLOBAL"
    ROBOT_LISTENER_API_VERSION: int = 2

    def __init__(self) -> None:
        configure_main_logger("pmi_ticket_collector")
        self.ROBOT_LIBRARY_LISTENER = self
        self._logger: logging.Logger = logging.getLogger("pmi_ticket_collector")
        self._zmq_ctx: zmq.Context = zmq.Context()
        self._cpue_instances: Dict[str, Dict[str, str]] = {}
        self._cprt_instances: Dict[str, Dict[str, str]] = {}
        self._connections: List[Tuple[Tunnel, zmq.Socket]] = []
        self._messages: List[Message] = []
        self._pmi_observers: dict = {}
        self._ue_mapping: Dict[str, List[str]] = {}
        self._tshark_sources: List[Union[CpUePMITsharkSource, CpRtPMITsharkSource]] = []
        self._cprt_socket_handlers: List[CpRtSocketsHandler] = []
        self._counters_definitions: Dict[str, Dict[str, str]] = {}
        self._cp_type: str = ""
        self._ssh_watcher: SSHWatcher
        self._ssh_fhd: Optional[TextIO] = None

    def _end_suite(self, name, attrs):
        self.stop_collecting_pmi_tickets()

    def prepare_pmi_tickets_config(self, cp_type="cpue") -> None:
        """
        Prepares PMI Ticket configuration, need to be called as 1st method from the library.

        :param str cp_type: type from where PMI Tickets should be gathered - CPUE, CPRT or BOTH
        """
        PluginsInstaller().install_required_wireshark_plugins()
        self._counters_definitions = CountersDefHandler().get_counter_definitions()
        self._cp_type = cp_type.lower()
        if cp_type == "cpue":
            self._prepare_pmi_tickets_config_for_cpue()
        elif cp_type == "cprt":
            self._prepare_pmi_tickets_config_for_cprt()
        elif cp_type == "both":
            self._prepare_pmi_tickets_config_for_cpue()
            self._prepare_pmi_tickets_config_for_cprt()
        else:
            raise NotImplementedError(f"CP type: [{cp_type}] is not yet supported")

    def _prepare_pmi_tickets_config_for_cpue(self) -> None:
        self._cpue_instances = {
            res["cpue_id"]: {
                "cu_ip": res["cu_ip"],
                "cpue_ip": res["cpue_ip"],
                "local_ip": f"127.0.0.{idx}",
                "username": res["user"],
                "password": res["password"],
            }
            for idx, res in enumerate(self._discover_cpue(), start=1)
        }

    def _prepare_pmi_tickets_config_for_cprt(self) -> None:
        self._cprt_instances = {str(idx): res for idx, res in enumerate(self._discover_cprt(), start=1)}

    def start_collecting_pmi_tickets(
        self, cpue: Union[List[str], str] = "all", cprt: Union[List[str], str] = "all"
    ) -> None:
        """
        Starts collecting PMI Tickets. Requires :class:`prepare_pmi_tickets_config` to be called before.

        :param list[str] | str cpue: IDs of CPUEs to be used
        :param list[str] | str cprt: IDs of CPUEs to be used
        """
        self._kill_all_remaining_tunnels_and_tsharks()
        if self._cp_type == "both":
            self._start_collecting_pmi_tickets_for_cpue(cpue)
            self._start_collecting_pmi_tickets_for_cprt(cprt)
        elif self._cp_type == "cpue":
            self._start_collecting_pmi_tickets_for_cpue(cpue)
        elif self._cp_type == "cprt":
            self._start_collecting_pmi_tickets_for_cprt(cprt)

    def _start_collecting_pmi_tickets_for_cpue(self, cpue: Union[List[str], str]) -> None:
        self._ssh_watcher = SSHWatcher(self._connections)
        self._ssh_watcher.start()
        self._ssh_fhd = open_ssh_fhd(self._logger)
        for cpue_instance in self._get_cp_instance(cpue, self._cpue_instances):
            tun = self._create_ssh_tunnel(cpue_instance)
            zmq_sock = self._connect_zmq(cpue_instance)
            self._connections.append((tun, zmq_sock))
        self._tshark_sources.append(CpUePMITsharkSource(partial(add_to_messages, self._messages)))

    def _start_collecting_pmi_tickets_for_cprt(self, cprt: Union[List[str], str]) -> None:
        for cprt_instance in self._get_cp_instance(cprt, self._cprt_instances):
            cprt_socket_handler = CpRtSocketsHandler(cprt_instance["s1u_local_ip4"], cprt_instance["cu_ip"])
            cprt_socket_handler.start()
            self._cprt_socket_handlers.append(cprt_socket_handler)
            cprt_instance.update(
                {"gnb_id": list(self._cprt_instances.keys())[list(self._cprt_instances.values()).index(cprt_instance)]}
            )
            self._tshark_sources.append(CpRtPMITsharkSource(cprt_instance, partial(add_to_messages, self._messages)))
            self._logger.debug(f"Started tshark for CPRT: {cprt_instance}")

    def stop_collecting_pmi_tickets(self) -> None:
        """
        Stops collection of PMI Tickets. Need to be always called at the end.
        """
        self._stop_all_tsharks()
        self._stop_collecting_pmi_tickets_for_cpue()
        self._stop_collecting_pmi_tickets_for_cprt()
        self._kill_all_remaining_tunnels_and_tsharks()

    def _stop_all_tsharks(self):
        for tshark in self._tshark_sources:
            tshark.stop()
        self._tshark_sources.clear()

    def _stop_collecting_pmi_tickets_for_cpue(self):
        for tunnel, zmq_sock in self._connections:
            self._close_ssh_tunnel(tunnel)
            self._close_zmq_socket(zmq_sock)
        self._connections.clear()
        self._stop_ssh_watcher()
        close_ssh_fhd(self._ssh_fhd)

    def _stop_ssh_watcher(self):
        try:
            self._ssh_watcher.stop()
        except AttributeError:
            self._logger.debug("SSH Watcher not created")

    def _stop_collecting_pmi_tickets_for_cprt(self):
        for cprt_socket_handler in self._cprt_socket_handlers:
            cprt_socket_handler.stop()

    def _kill_all_remaining_tunnels_and_tsharks(self) -> None:
        kill_all_processes_with_name("/tmp/pmi_ticket", self._logger)
        kill_all_processes_with_name("-f tcp src port 30512 -l", self._logger)
        kill_all_processes_with_name("src port 15066", self._logger)
        remove_ssh_files()

    def _close_zmq_socket(self, zmq_sock: zmq.Socket) -> None:
        endpoint = cast(bytes, zmq_sock.LAST_ENDPOINT).decode("utf8")
        zmq_sock.close()
        self._logger.debug(f"Closed ZMQ {endpoint}")

    @ssh_tunnels_checker
    def get_all_pmi_tickets(self) -> List[Message]:
        """
        Returns all collected PMI Tickets.

        :return: list[:class:`Message`]: List of collected PMI Tickets
        """
        return self._messages

    @ssh_tunnels_checker
    def get_pmi_tickets_per_cpue(self, cpues: Union[List[str], str]) -> List[Message]:
        """
        Returns all PMI Tickets for specified CPUEs

        :param list[str] | str cpues: IDs of CPUEs to be used
        :return: list[:class:`Message`]: List of collected PMI Tickets
        """
        cpues = self._split_user_data_into_list(cpues)
        cpues_local_ips = [self._cpue_instances[cp_ue]["local_ip"] for cp_ue in cpues]
        return [msg for msg in self._messages if msg.src_ip in cpues_local_ips]

    @ssh_tunnels_checker
    def get_pmi_tickets_per_cprt(self, cprts: Union[List[str], str]) -> List[Message]:
        """
        Returns all PMI Tickets for specified CPRTs

        :param list[str] | str cprts: IDs of CPRTs to be used
        :return: list[:class:`Message`]: List of collected PMI Tickets
        """
        cprts = self._split_user_data_into_list(cprts)
        return [msg for msg in self._messages if hasattr(msg, "gnb_id") and msg.gnb_id in cprts]

    @ssh_tunnels_checker
    def get_pmi_ticket_per_nrcellid(self, nrcellid: Union[List[str], str]) -> List[Message]:
        """
        Returns all PMI Tickets for specified NRCellId

        :param list[str] | str nrcellid: IDs of NRCells to be used
        :return: list[:class:`Message`]: List of collected PMI Tickets
        """
        nrcellids = self._split_user_data_into_list(nrcellid)
        return [msg for msg in self._messages if msg.get("nrCellId") in nrcellids]

    @ssh_tunnels_checker
    def get_all_pmi_tickets_for_ue(self, ue_alias: str) -> List[Message]:
        """
        Returns all PMI Tickets for specified UE.

        :param str ue_alias: alias provided to the :class:`save_last_ue_with_alias` method.
        :return: list[:class:`Message`]: List of collected PMI Tickets
        """
        return [msg for msg in self._messages if msg.get("cuUeId", "0") in self._ue_mapping[ue_alias]]

    @ssh_tunnels_checker
    def save_last_ue_with_alias(self, ue_alias: str) -> None:
        """
        | Gets cuUeId from last PMI Ticket and saves it using specified alias.
        | It creates internal mapping like: {ue_name_1: 123456, ...}

        :param str ue_alias: Name which should store last cuUeId of last PMI Ticket.
        """
        self._ue_mapping.update({ue_alias: [self._messages[-1].get("cuUeId", "0")]})

    @ssh_tunnels_checker
    def save_additional_id_for_ue_with_alias(self, ue_alias: str) -> None:
        """
        | Gets cuUeId from last PMI Ticket and saves it as additional one for already existing alias.
        | This is useful if e.g. UE gets detached in the meantime or HO and we would like to check all PMI Tickets
          for that UE, but cuUeId will be different between attaches.

        | It creates internal mapping like: {ue_name_1: [123456, 456789], ...}.

        :param str ue_alias: Name which should store last cuUeId of last PMI Ticket.
        """
        self._ue_mapping[ue_alias].append(self._messages[-1].get("cuUeId", "0"))

    def clear_pmi_tickets(self) -> None:
        """Clears all collected PMI Tickets."""
        self._messages.clear()

    @ssh_tunnels_checker
    def verify_pmi_counters_in_records(self, *pmi_counters: str) -> None:
        """
        | Verifies PMI counter inside all the collected PMI Tickets.
        | Should be used as: :class:`verify_pmi_counters_in_records(X2_SHUTDOWN_DETECTED==2, ...)`

        +----------------------+----------+-------+
        | CounterID            | Operator | Value |
        +======================+==========+=======+
        | 3611688962           |    ==    | 3     |
        +----------------------+----------+-------+
        | X2_SHUTDOWN_DETECTED |    eq    | 2     |
        +----------------------+----------+-------+
        | M55110C00002         |    !=    |   1   |
        +----------------------+----------+-------+

        | You can use either name of counter or a number that represent that one.
        | Possible values for operators:

        +--------------+------+---------+
        | name         | sign | literal |
        +==============+======+=========+
        | equal        |  ==  |    eq   |
        +--------------+------+---------+
        | not equal    |  !=  |    ne   |
        +--------------+------+---------+
        | greater then |  >=  |    ge   |
        +--------------+------+---------+
        | greater      |  >   |    gt   |
        +--------------+------+---------+
        | lesser then  |  <=  |    lt   |
        +--------------+------+---------+
        | lesser       |  <   |    le   |
        +--------------+------+---------+

        """
        counters_from_msgs = self._get_counters_with_occurrences()
        counters = parse_counters_to_check(pmi_counters)
        self._logger.debug(f"PMI Counters to be validated: {counters}")
        self._check_counters_by_type(counters, counters_from_msgs)

    @ssh_tunnels_checker
    def wait_for_next_pmi_record(self, alias: str, timeout: Union[float, str] = 10) -> None:
        """
        Creates an observer for next PMI record. Must be checked with :class:`check_pmi_record_received` if message
        was actually received.

        :param str alias: Name of observer that can be used to check for PMI record later on.
        :param float | str timeout: timeout in seconds how long to wait for a next message. Default value is 10s.
        """
        self._pmi_observers[alias] = {
            "timeout": float(timeout),
            "t_start": time.time(),
            "len": len(self._messages),
        }

    @ssh_tunnels_checker
    def check_pmi_record_received(self, alias: str) -> None:
        """
        | Checks if PMI record specified with :class:`wait_for_next_pmi_record` was received.
        | This method blocks until specified timeout for particular record has been reached.

        :param str alias: Name of observer that can be used to check for PMI record later on.
        """
        t_start, timeout = (
            self._pmi_observers[alias]["t_start"],
            self._pmi_observers[alias]["timeout"],
        )
        n = self._pmi_observers[alias]["len"]
        while time.time() - t_start < timeout:
            if len(self._messages) > n:
                del self._pmi_observers[alias]
                break
        else:
            raise TimeoutError("PMI not received")

    @staticmethod
    def _get_msg_fulfilling_requirement(msg: Message, requirement: str) -> Message:
        try:
            return msg.get_value_by_unique_key(requirement)
        except (NotFoundKey, AmbiguousKey):
            return Message({}, {})

    @ssh_tunnels_checker
    def verify_event_with_field(
        self,
        event_name: str,
        field_name: str,
        value: Optional[str] = None,
        nrcellid: Optional[str] = None,
    ) -> bool:
        """
        | Checks if "event" is in any PMI Record and contains field with an optional value.
        | You can specify NrCellId to limit PMI Records.

        Let's say there is a structure like that in PMI Record:

        | {"eventOccurences": [{
        |     "ueDuConnectivity": {
        |         "eventResult": {
        |             "primaryResult": 1,
        |             "secondaryResult": 0
        |             }}}]}

        You can check if e.g. `"primaryResult"` was in `"ueDuConnectivity"` and optionally if it was set to "1".

        :param str event_name: Name an event that should be looked inside PMI Records.
        :param str field_name: Name of a field that should be looked inside event of PMI Record.
        :param Optional[str] value: Value of the field that should be compared.
        :param Optional[str] nrcellid: ID of NR Cell to limit PMI Records to just that cell.
        """
        msgs = list(self._messages)
        if nrcellid:
            msgs = [msg for msg in msgs if msg["nrCellId"] == nrcellid]
        for msg in msgs:
            event = self._get_msg_fulfilling_requirement(msg, event_name)
            try:
                field_value = event.get_value_by_unique_key(field_name)
                if (value and value == field_value) or not value:
                    return True
            except NotFoundKey:
                continue
        self._logger.warning(
            pformat(f"Event: {event_name} with field: {field_name} not found.\n{json.dumps(self._messages)}")
        )
        raise KeyError(f"Event: {event_name} with field: {field_name} not found.")

    @ssh_tunnels_checker
    def verify_event_with_field_did_not_occur(
        self,
        event_name: str,
        field_name: Optional[str] = None,
        nrcellid: Optional[str] = None,
    ) -> bool:
        """
        | Checks if event with optional field name was not present in any PMI Record.
        | You can specify NrCellId to limit PMI Records.
        | For detailed information check :class:`verify_event_with_field`.

        :param str event_name: Name an event that should be looked inside PMI Records.
        :param str field_name: Name of a field that should be looked inside event of PMI Record.
        :param Optional[str] nrcellid: ID of NR Cell to limit PMI Records to just that cell.
        """
        msgs = list(self._messages)
        if nrcellid:
            msgs = [msg for msg in msgs if msg["nrCellId"] == nrcellid]
        for msg in msgs:
            event = self._get_msg_fulfilling_requirement(msg, event_name)
            try:
                if not event or event.key_not_occurred(field_name):
                    continue
            except FoundKey:
                self._logger.warning(f"Event: {event_name} with field {field_name} was found!")
                self._logger.warning(pformat(msg))
                raise KeyError(f"Event: {event_name} with field {field_name} was found!")
        return True

    def _read_testline_configuration(self) -> List[Dict[str, str]]:
        tl_config = get_tl_config(self._logger)
        return [
            {
                "cu_ip": gnb.cu.oam_ssh_connection_details.addr,
                "s1u_local_ip4": gnb.cu.s1u.v4,
                "user": gnb.cu.oam_ssh_connection_details.username,
                "password": gnb.cu.oam_ssh_connection_details.password,
            }
            for gnb in tl_config.gnbs
        ]

    def _discover_cprt(self) -> Generator[Dict[str, str], None, None]:
        yield from self._read_testline_configuration()

    def _discover_cpue(self) -> Generator[Dict[str, str], None, None]:
        for gnb_data in self._read_testline_configuration():
            yield from find_cpue_on_gnb(gnb_data, self._logger)

    def __get_cp_from_list(
        self, user_choice: List[str], cp_data: Dict[str, Dict[str, str]]
    ) -> Generator[Dict[str, str], None, None]:
        for cp in user_choice:
            try:
                yield cp_data[cp]
            except KeyError:
                self._logger.error(f"Not found CP-{cp}. Possible IDs: {cp_data.keys()}")
                raise

    def _get_cp_instance(
        self, user_choice: Union[List[str], str], cp_data: Dict[str, Dict[str, str]]
    ) -> Generator[Dict[str, str], None, None]:
        if isinstance(user_choice, str):
            if user_choice.strip().lower() == "all":
                yield from cp_data.values()
            else:
                user_choice = self._split_user_data_into_list(user_choice)
                yield from self.__get_cp_from_list(user_choice, cp_data)
        else:
            yield from self.__get_cp_from_list(user_choice, cp_data)

    @staticmethod
    def _split_user_data_into_list(user_data: Union[List[str], str]) -> List[str]:
        if isinstance(user_data, (list, tuple)):
            return [data.strip() for data in user_data]
        elif isinstance(user_data, str):
            return [data.strip() for data in user_data.replace(",", " ").split()]

    def _create_ssh_tunnel(self, cpue_instance: Dict[str, str]) -> Tunnel:
        cpue_ip, cu_ip, local_ip = (
            cpue_instance["cpue_ip"],
            cpue_instance["cu_ip"],
            cpue_instance["local_ip"],
        )
        username, password = cpue_instance["username"], cpue_instance["password"]
        tun_name = f"/tmp/pmi_ticket_{local_ip}_{cpue_ip}"
        tun = Tunnel(cu_ip, local_ip, cpue_ip, tun_name, username, password)
        tun.start(self._ssh_fhd)
        if tun.is_alive():
            return tun
        raise SSHTunnelError(f"Tunnel did not start. Messages will not be collected. {tun}")

    def _connect_zmq(self, cpue_instance: Dict[str, str]) -> zmq.Socket:
        sock = self._zmq_ctx.socket(zmq.PULL)
        sock.setsockopt(zmq.IPV6, 1)
        newaddr = f"tcp://{cpue_instance['local_ip']}:30512"
        sock.connect(newaddr)
        self._logger.debug(f"Created ZMQ connection: {newaddr}")
        return sock

    def _close_ssh_tunnel(self, tunnel: Tunnel) -> None:
        tunnel.close(self._ssh_fhd)

    def _get_counter_dev_name(self, counter: str, _type: str) -> str:
        counter_dev_name = ""
        for counter_dev, counter_data in self._counters_definitions.items():
            if counter_data[_type] == counter:
                counter_dev_name = counter_dev
                break
        return counter_dev_name

    def _check_counters_by_type(
        self,
        counters_to_be_checked: Dict[str, Dict[str, str]],
        counters_from_msgs: Dict[str, int],
    ) -> None:
        if all(1 if re.search(r"^(M[A-Z0-9]+)$", counter) else 0 for counter in counters_to_be_checked.keys()):  # M*
            counters_from_msgs = self.__convert_counters_to_values(counters_from_msgs)
            counters_with_dev_name = {
                counter: {
                    "occurrence": occurrence,
                    "dev_name": self._get_counter_dev_name(counter, "value"),
                }
                for counter, occurrence in counters_from_msgs.items()
            }
        elif all(1 if counter.find("_") != -1 else 0 for counter in counters_to_be_checked.keys()):
            counters_from_msgs = self.__convert_counters_to_names(counters_from_msgs)
            counters_with_dev_name = {
                counter: {
                    "occurrence": occurrence,
                    "dev_name": self._get_counter_dev_name(counter, "name"),
                }
                for counter, occurrence in counters_from_msgs.items()
            }
        elif all(1 if counter.isdigit() else 0 for counter in counters_to_be_checked.keys()):
            counters_from_msgs = dict(counters_from_msgs)
            counters_with_dev_name = {
                counter: {"occurrence": occurrence, "dev_name": counter}
                for counter, occurrence in counters_from_msgs.items()
            }
        else:
            raise ValueError(
                f"Mixed different type of counters [{counters_to_be_checked}]. Use either dev values, "
                f"M* values or whole names."
            )
        self._logger.debug(f"PMI Counters found in records: {counters_with_dev_name}")
        self._verify_all_counters_with_occurrences(counters_to_be_checked, counters_from_msgs)

    def __convert_counters_to_values(self, counters: Dict[str, int]) -> Dict[str, int]:
        return {self._counters_definitions[counter]["value"]: occurrence for counter, occurrence in counters.items()}

    def __convert_counters_to_names(self, counters: Dict[str, int]) -> Dict[str, int]:
        return {self._counters_definitions[counter]["name"]: occurrence for counter, occurrence in counters.items()}

    def _get_counters_with_occurrences(self) -> Dict[str, int]:
        ret = []
        for m in self._messages:
            try:
                for pm_counter_values in m.get_all_values_by_key("pmCounterId"):
                    ret.append(pm_counter_values)
            except NotFoundKey:
                continue
        return Counter(ret)

    @staticmethod
    def _verify_all_counters_with_occurrences(
        counters_to_be_checked: Dict[str, Dict[str, str]],
        counters_from_msgs: Dict[str, int],
    ) -> None:
        for counter, counter_data in counters_to_be_checked.items():
            try:
                counter_from_msg = counters_from_msgs[counter]
                if counter_data["operator"].isalpha():
                    cmd = f"int({counter_from_msg}).__{counter_data['operator']}__(int({counter_data['value']}))"
                else:
                    cmd = f"int({counter_from_msg}) {counter_data['operator']} int({counter_data['value']})"
                assert eval(cmd), (
                    f'{counter} expected occurrence: "{counter_data["operator"]} {counter_data["value"]}". '
                    f"Found occurrence: {counter_from_msg}"
                )
            except KeyError as exc:
                if counter_data["operator"] in ("==", "eq") and int(counter_data["value"]) == 0:
                    return
                raise KeyError(f"Counter '{counter}' not found in PMI Ticket") from exc
